CREATE TABLE `platform_role_assignments` (`user_id` CHAR(36) CHARACTER SET ascii NOT NULL,`role_code` VARCHAR(64) CHARACTER SET ascii NOT NULL,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`user_id`,`role_code`),KEY `idx_platform_roles_role`(`role_code`,`user_id`),CONSTRAINT `fk_platform_roles_user` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_roles_role` FOREIGN KEY(`role_code`) REFERENCES `roles`(`code`) ON DELETE RESTRICT,CONSTRAINT `fk_platform_roles_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
